ForAll(
    Sort(
        GroupBy(
            Filter(
                'Milestones Standard Assumptions',
                Country.Country = GUID(lbl_CountryGuid_MilestoneStandardAssumptions_AdminScreen.Text)
            ),
            Technology,
            Techs
        ),
        vsb_technology,
        SortOrder.Ascending
    ) As techGroups,
    With(
        {
            Durations: LookUp(
                techGroups.Techs,
                Name = "average duration [months]"
            ),
            SuccessRates: LookUp(
                techGroups.Techs,
                Name = "success rate [-]"
            )
        },
        {
            Technology: techGroups.vsb_technology,
            Entries: [
                {
                    Label: "Cluster 1",
                    Duration: Durations.'Cluster 1',
                    SuccessRate: SuccessRates.'Cluster 1'
                },
                {
                    Label: "Cluster 2",
                    Duration: Durations.'Cluster 2',
                    SuccessRate: SuccessRates.'Cluster 2'
                },
                {
                    Label: "Cluster 3",
                    Duration: Durations.'Cluster 3',
                    SuccessRate: SuccessRates.'Cluster 3'
                },
                {
                    Label: "Cluster 4",
                    Duration: Durations.'Cluster 4',
                    SuccessRate: SuccessRates.'Cluster 4'
                },
                {
                    Label: "FID",
                    Duration: Durations.'Final Investment Decision',
                    SuccessRate: 1
                },
                {
                    Label: "Cluster 5",
                    Duration: Durations.'Cluster 5',
                    SuccessRate: SuccessRates.'Cluster 5'
                },
                {
                    Label: "Operational Lifetime",
                    Duration: Durations.'Operational Lifetime',
                    SuccessRate: SuccessRates.'Operational Lifetime'
                },
                {
                    Label: "Sales Start",
                    Duration: Durations.'Sales Start',
                    SuccessRate: SuccessRates.'Sales Start'
                },
                {
                    Label: "Sales Duration",
                    Duration: Durations.'Sales End',
                    SuccessRate: SuccessRates.'Sales End'
                }
            ]
        }
    )
)

With(
    {
        record: LookUp(
